import java.time.*;
import java.time.temporal.ChronoUnit;

public class LocalDateArithmetic {
    public static void main(String[] args) {
        LocalDate start = LocalDate.of(2024, 1, 1);

        System.out.println(start.plusDays(90));         // 2024-03-31
        System.out.println(start.minusMonths(2));       // 2023-11-01
        System.out.println(start.plusYears(1).plusMonths(3)); // 2025-04-01

        LocalDate end = LocalDate.of(2024, 12, 31);

        long days   = ChronoUnit.DAYS.between(start, end);
        long weeks  = ChronoUnit.WEEKS.between(start, end);
        long months = ChronoUnit.MONTHS.between(start, end);

        System.out.println("Days:   " + days);   // 365
        System.out.println("Weeks:  " + weeks);  // 52
        System.out.println("Months: " + months); // 11

        // Equivalent: using until()
        System.out.println(start.until(end, ChronoUnit.DAYS)); // 365
    }
}

