import java.time.*;
import java.util.stream.Collectors;

public class ZonedDateTimeBasics {
    public static void main(String[] args) {
        ZonedDateTime nyNow  = ZonedDateTime.now(ZoneId.of("America/New_York"));
        ZonedDateTime tokNow = ZonedDateTime.now(ZoneId.of("Asia/Tokyo"));
        System.out.println("NY:    " + nyNow);
        System.out.println("Tokyo: " + tokNow);

        // Specific time in London
        ZonedDateTime london = ZonedDateTime.of(
            LocalDateTime.of(2024, 6, 15, 9, 0), ZoneId.of("Europe/London"));
        System.out.println("London: " + london); // 2024-06-15T09:00+01:00[Europe/London]

        // Convert to New York: SAME instant, different offset
        ZonedDateTime newYork = london.withZoneSameInstant(ZoneId.of("America/New_York"));
        System.out.println("New York (same instant): " + newYork); // 2024-06-15T04:00...

        // withZoneSameLocal: same clock reading (09:00), but NOW in New York's zone
        // This is a DIFFERENT instant — 5 hours later than the London time
        ZonedDateTime nyLocal = london.withZoneSameLocal(ZoneId.of("America/New_York"));
        System.out.println("New York (same local):   " + nyLocal); // 2024-06-15T09:00...
        System.out.println("Same instant? " + newYork.toInstant().equals(nyLocal.toInstant())); // false

        // Available zones containing "America"
        ZoneId.getAvailableZoneIds().stream()
            .filter(z -> z.startsWith("America"))
            .sorted().limit(5)
            .forEach(System.out::println);
    }
}

