import java.time.*;
import java.time.format.*;
import java.util.Locale;

public class AdvancedFormatting {
    public static void main(String[] args) {
        ZonedDateTime zdt = ZonedDateTime.of(
            LocalDateTime.of(2024, 3, 15, 9, 30),
            ZoneId.of("America/New_York"));

        DateTimeFormatter rfcStyle = DateTimeFormatter
            .ofPattern("EEE, dd MMM yyyy HH:mm z", Locale.ENGLISH);
        System.out.println(zdt.format(rfcStyle)); // Fri, 15 Mar 2024 09:30 EDT

        // STRICT parsing — rejects invalid dates
        DateTimeFormatter strict = DateTimeFormatter
            .ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);
        try {
            LocalDate.parse("2024-02-30", strict); // throws
        } catch (DateTimeException e) {
            System.out.println("Strict rejected: " + e.getMessage());
        }
        LocalDate leapDay = LocalDate.parse("2024-02-29", strict);
        System.out.println("Leap day OK: " + leapDay); // 2024-02-29

        // LENIENT parsing — rolls over invalid dates
        DateTimeFormatter lenient = DateTimeFormatter
            .ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.LENIENT);
        LocalDate rolled = LocalDate.parse("2024-02-30", lenient);
        System.out.println("Lenient rolled: " + rolled); // 2024-03-01
    }
}

