import java.time.*;
import java.util.Date;
import java.util.Calendar;

public class LegacyBridge {
    public static void main(String[] args) {
        Date legacyDate = new Date();

        // Date -> Instant
        Instant instant = legacyDate.toInstant();
        System.out.println("Instant: " + instant);

        // Instant -> LocalDate (in system timezone)
        LocalDate localDate = instant
            .atZone(ZoneId.systemDefault())
            .toLocalDate();
        System.out.println("LocalDate: " + localDate);

        // Instant -> LocalDateTime in UTC
        LocalDateTime utcDT = instant
            .atZone(ZoneOffset.UTC)
            .toLocalDateTime();
        System.out.println("UTC LocalDateTime: " + utcDT);

        // LocalDateTime -> Date (must specify a zone)
        LocalDateTime modern = LocalDateTime.of(2024, 6, 15, 12, 0);
        Date legacyBack = Date.from(
            modern.atZone(ZoneId.systemDefault()).toInstant());
        System.out.println("Back to Date: " + legacyBack);

        // Calendar -> ZonedDateTime
        Calendar cal = Calendar.getInstance();
        ZonedDateTime zdt = cal.toInstant()
            .atZone(cal.getTimeZone().toZoneId());
        System.out.println("From Calendar: " + zdt);
    }
}

