import java.time.*;
import java.time.temporal.TemporalAdjusters;

public class TemporalAdjustersDemo {
    public static void main(String[] args) {
        LocalDate date = LocalDate.of(2024, 3, 15); // Friday

        System.out.println(date.with(TemporalAdjusters.firstDayOfMonth())); // 2024-03-01
        System.out.println(date.with(TemporalAdjusters.lastDayOfMonth()));  // 2024-03-31

        System.out.println(date.with(TemporalAdjusters.firstInMonth(DayOfWeek.MONDAY)));  // 2024-03-04
        System.out.println(date.with(TemporalAdjusters.next(DayOfWeek.FRIDAY)));          // 2024-03-22
        System.out.println(date.with(TemporalAdjusters.nextOrSame(DayOfWeek.FRIDAY)));    // 2024-03-15 (today!)
        System.out.println(date.with(TemporalAdjusters.nextOrSame(DayOfWeek.MONDAY)));   // 2024-03-18

        System.out.println(date.with(TemporalAdjusters.lastInMonth(DayOfWeek.SUNDAY)));  // 2024-03-31

        // Custom adjuster: next business day (Mon-Fri)
        TemporalAdjusters.ofDateAdjuster(d -> {
            DayOfWeek dow = d.getDayOfWeek();
            int add = (dow == DayOfWeek.FRIDAY) ? 3 :
                      (dow == DayOfWeek.SATURDAY) ? 2 : 1;
            return d.plusDays(add);
        });
        System.out.println("Next biz after Fri: " + date.with(
            TemporalAdjusters.ofDateAdjuster(d -> {
                DayOfWeek dow = d.getDayOfWeek();
                int add = (dow == DayOfWeek.FRIDAY) ? 3 : (dow == DayOfWeek.SATURDAY) ? 2 : 1;
                return d.plusDays(add);
            })
        )); // 2024-03-18 (Monday)
    }
}

