import java.time.*;

public class DSTTransition {
    public static void main(String[] args) {
        ZoneId eastern = ZoneId.of("America/New_York");

        // Just before spring forward: 01:30 EST (UTC-5)
        ZonedDateTime before = ZonedDateTime.of(
            LocalDateTime.of(2024, 3, 10, 1, 30), eastern);
        System.out.println("Before: " + before); // 2024-03-10T01:30-05:00[America/New_York]

        // Add 1 hour (3600 seconds): lands in the gap -> adjusted to 03:30 EDT (UTC-4)
        ZonedDateTime after = before.plus(Duration.ofHours(1));
        System.out.println("After +1h: " + after); // 2024-03-10T03:30-04:00[America/New_York]
        // Wall clock jumped from 01:30 to 03:30 — 2 clock hours advanced, not 1!

        // Fall-back overlap: 01:30 is ambiguous — it occurs twice
        ZonedDateTime overlap = ZonedDateTime.of(
            LocalDateTime.of(2024, 11, 3, 1, 30), eastern);
        System.out.println("\nOverlap (default EDT): " + overlap);

        ZonedDateTime earlier = overlap.withEarlierOffsetAtOverlap();
        ZonedDateTime later   = overlap.withLaterOffsetAtOverlap();
        System.out.println("Earlier offset (EDT -04): " + earlier);
        System.out.println("Later  offset (EST -05): " + later);
        System.out.println("Instant difference: " +
            Duration.between(earlier.toInstant(), later.toInstant()).toHours() + " hour(s)"); // 1
    }
}

