import java.time.*;
import java.util.*;

public class MeetingScheduler {

    static List<LocalDateTime> generateWeekly(LocalDateTime firstMeeting, int count) {
        List<LocalDateTime> meetings = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            meetings.add(firstMeeting.plusWeeks(i));
        }
        return meetings;
    }

    static boolean overlaps(LocalDateTime a, LocalDateTime b, int durationMinutes) {
        LocalDateTime aEnd = a.plusMinutes(durationMinutes);
        LocalDateTime bEnd = b.plusMinutes(durationMinutes);
        // Overlap: each starts before the other ends
        return a.isBefore(bEnd) && b.isBefore(aEnd);
    }

    static Duration timeUntilNext(LocalDateTime now, List<LocalDateTime> meetings) {
        return meetings.stream()
            .filter(m -> m.isAfter(now))
            .min(Comparator.naturalOrder())
            .map(m -> Duration.between(now, m))
            .orElse(Duration.ZERO);
    }

    public static void main(String[] args) {
        LocalDateTime first = LocalDateTime.of(2024, 1, 8, 10, 0);
        List<LocalDateTime> schedule = generateWeekly(first, 4);
        schedule.forEach(System.out::println);
        // 2024-01-08T10:00, 2024-01-15T10:00, 2024-01-22T10:00, 2024-01-29T10:00

        System.out.println(overlaps(
            LocalDateTime.of(2024, 1, 8, 10, 0),
            LocalDateTime.of(2024, 1, 8, 10, 30), 60)); // true
        System.out.println(overlaps(
            LocalDateTime.of(2024, 1, 8, 10, 0),
            LocalDateTime.of(2024, 1, 8, 11, 0), 60)); // false (b starts at a's end)

        LocalDateTime now = LocalDateTime.of(2024, 1, 8, 9, 45);
        System.out.println(timeUntilNext(now, schedule)); // PT15M
    }
}
